function slugify(input) {
  if (typeof input !== "string") throw new TypeError("slugify expects a string");
  return input
    .replace(/\u00df/g, "ss")
    .replace(/\u1e9e/g, "SS")
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

export { slugify };
